from fractions import Fraction as F


def original(a):
    """Evaluate the original expression exactly; raise ZeroDivisionError outside its domain."""
    a = F(a)
    den1 = a * a + 6 * a + 9      # (a+3)^2 must be nonzero
    num2 = a - 3                  # divisor (a-3)/(a^2+3a) must be nonzero
    den2 = a * a + 3 * a          # divisor's denominator must be nonzero
    den3 = a - 1                  # (a-a^2)/(a-1) needs a != 1
    if den1 == 0 or num2 == 0 or den2 == 0 or den3 == 0:
        raise ZeroDivisionError
    t1 = F(a * a - 9) / den1
    t2 = t1 / (F(num2) / den2)    # division of fractions
    t3 = F(a - a * a) / den3
    return t2 - t3


